#!/usr/bin/env bash
# GENERATED by hecks deploy project -- re-run it to refresh this file rather than hand-editing.
# Settings come from the domain's deployed_to("AwsBox") block (hosting_scripts true).
#
# Deploys ONE container's freshly built local image to widget-shop's app box, under a fresh, unique ECR tag.
#
#   bash deploy-service.sh <service>
#   EXISTING_TAG=<tag> bash deploy-service.sh <service>    redeploy a tag already in ECR (no push)
#
# Why it exists: pushing a floating tag and restarting a container looks like a deploy, but nothing
# records which image the box was told to run, and a box that pulls a tag it already has keeps the old
# image. This script pushes the local image under a never-reused tag (<service>-<UTC timestamp>),
# refuses a tag that is already in ECR, and names that tag in the roll.
# It then sets the stack's matching image-tag parameter (UsePreviousValue for every other
# one, and it checks that only that one changed), reads the task definition the stack
# registers, refuses to roll it unless it carries the pushed image, and rolls it with
# deploy-box.sh.
#
# It ends with smoke-after-deploy.sh, whose own exit codes (20-23) are distinct from a failed deploy
# step's. SKIP_POST_DEPLOY_SMOKE=1 skips it. `hecks deploy service_roll.run` runs this script with
# SMOKE_BY_COMMAND=1, which ends after the roll and leaves the smoke to the smoke_run.run its policy requests.
#
# Exit codes (the ones `service_roll.run` names; a step that fails under `set -e` ends with its own
# status, 1 from bash and 254/255 from the aws CLI):
#   2   unknown service
#   30  EXISTING_TAG is not in ECR              31  the fresh tag is already in ECR
#   32  the box's Compose file is unreadable    33  the box stack has no instance
#   34  the stack has no parameter for the container   35  the stack update failed or did not settle
#   36  a parameter other than the container's changed  37  the task definition lacks the pushed image
#   38  the task definition has no such container      40-43  deploy-box.sh's own
#
# Environment:
#   LOCAL_IMAGE               local image to push, default <ecr repository>:latest
#   EXISTING_TAG              redeploy this tag from ECR instead of building and pushing
#   SETTLE_TIMEOUT_SECS       default 1200, how long to wait for a stack update
#   SKIP_POST_DEPLOY_SMOKE=1  passed through to smoke-after-deploy.sh
#   SMOKE_BY_COMMAND=1        end after the roll and print `rolled taskdef=<td> tag=<tag>`; the caller smokes
set -euo pipefail

REGION=us-east-1
FAMILY=widget-platform
IMAGE_STACK=widget-platform

SERVICES='website cms domain'

# Sets the container's settings for one service, or exits.
resolve_service() {
  case "$1" in
    website) CFN_PARAM_KEY=WebsiteImageTag ;;
    cms) CFN_PARAM_KEY=CmsImageTag ;;
    domain) CFN_PARAM_KEY=EngineImageTag ;;
    *) echo "unknown service '$1', must be one of: ${SERVICES}" >&2; exit 2 ;;
  esac
}

SERVICE_NAME="${1:?usage: deploy-service.sh <service> (one of: ${SERVICES})}"
resolve_service "$SERVICE_NAME"

cd "$(dirname "${BASH_SOURCE[0]}")"
SETTLE_TIMEOUT_SECS="${SETTLE_TIMEOUT_SECS:-1200}"
ACCOUNT_ID="$(aws sts get-caller-identity --query Account --output text)"
ECR_HOST="${ACCOUNT_ID}.dkr.ecr.${REGION}.amazonaws.com"
SCRATCH_DIR="$(mktemp -d)"
trap 'rm -rf "$SCRATCH_DIR"' EXIT

# True once $1 (a value of $SECONDS) is further in the past than the settle timeout.
timed_out() { [ $((SECONDS - $1)) -gt "$SETTLE_TIMEOUT_SECS" ]; }

# The active task definition names the image repository of every container, so the push goes where
# the box already pulls from.
active_image() {
  aws ecs describe-task-definition --task-definition "$FAMILY" --region "$REGION" \
    --query "taskDefinition.containerDefinitions[?name=='${SERVICE_NAME}'].image | [0]" --output text
}
CURRENT_IMAGE="$(active_image)"
case "$CURRENT_IMAGE" in
  None|"") echo "task definition family ${FAMILY} has no container named ${SERVICE_NAME}" >&2; exit 38 ;;
esac
ECR_REPOSITORY="${CURRENT_IMAGE#*/}"
ECR_REPOSITORY="${ECR_REPOSITORY%%[:@]*}"

TAG="${EXISTING_TAG:-${SERVICE_NAME}-$(date -u +%Y%m%d%H%M%S)}"
IMAGE_URI="${ECR_HOST}/${ECR_REPOSITORY}:${TAG}"
LOCAL_IMAGE="${LOCAL_IMAGE:-${ECR_REPOSITORY}:latest}"

if [ -n "${EXISTING_TAG:-}" ]; then
  echo "==> reusing ${IMAGE_URI} (no push)"
  aws ecr describe-images --repository-name "$ECR_REPOSITORY" --region "$REGION" \
    --image-ids "imageTag=${TAG}" --query 'imageDetails[0].imageTags' --output text > /dev/null \
    || { echo "tag ${TAG} is not in ECR" >&2; exit 30; }
else
  if aws ecr describe-images --repository-name "$ECR_REPOSITORY" --region "$REGION" \
      --image-ids "imageTag=${TAG}" > /dev/null 2>&1; then
    echo "tag ${TAG} is already in ECR; a tag is never reused. Run again." >&2
    exit 31
  fi
  echo "==> tagging ${LOCAL_IMAGE} as ${IMAGE_URI}"
  docker tag "$LOCAL_IMAGE" "$IMAGE_URI"

  # A private docker config with no credential helper: a helper that blocks on a keychain prompt
  # hangs forever in any unattended shell.
  echo "==> ecr login"
  DOCKER_CONFIG_DIR="${SCRATCH_DIR}/docker-config"
  mkdir -p "$DOCKER_CONFIG_DIR"
  echo '{}' > "${DOCKER_CONFIG_DIR}/config.json"
  aws ecr get-login-password --region "$REGION" \
    | docker --config "$DOCKER_CONFIG_DIR" login --username AWS --password-stdin "$ECR_HOST"

  echo "==> pushing ${IMAGE_URI}"
  docker --config "$DOCKER_CONFIG_DIR" push "$IMAGE_URI"
fi

echo "==> setting the stack's ${CFN_PARAM_KEY} to ${TAG} (registers the new task definition revision)"
stack_parameters() {
  aws cloudformation describe-stacks --stack-name "$IMAGE_STACK" --region "$REGION" \
    --query 'Stacks[0].Parameters[].{k:ParameterKey,v:ParameterValue}' --output json
}
stack_parameters > "${SCRATCH_DIR}/params-before.json"
ALL_PARAM_KEYS="$(jq -r '.[].k' "${SCRATCH_DIR}/params-before.json")"
CFN_ARGS=()
found=0
for key in $ALL_PARAM_KEYS; do
  if [ "$key" = "$CFN_PARAM_KEY" ]; then
    CFN_ARGS+=("ParameterKey=${key},ParameterValue=${TAG}")
    found=1
  else
    CFN_ARGS+=("ParameterKey=${key},UsePreviousValue=true")
  fi
done
if [ "$found" != "1" ]; then
  echo "stack ${IMAGE_STACK} has no parameter named ${CFN_PARAM_KEY}; the image was pushed but nothing was rolled" >&2
  exit 34
fi

if UPDATE_OUT="$(aws cloudformation update-stack --stack-name "$IMAGE_STACK" --region "$REGION" \
    --use-previous-template --capabilities CAPABILITY_IAM --parameters "${CFN_ARGS[@]}" \
    --query 'StackId' --output text 2>&1)"; then
  echo "==> waiting for the CloudFormation stack update to settle"
  started=$SECONDS
  while true; do
    stack_status="$(aws cloudformation describe-stacks --stack-name "$IMAGE_STACK" --region "$REGION" \
      --query 'Stacks[0].StackStatus' --output text)"
    case "$stack_status" in
      UPDATE_COMPLETE) echo "    -> ${stack_status}"; break ;;
      *ROLLBACK*|*FAILED*)
        echo "    -> ${stack_status}: the stack update failed, investigate before rolling anything" >&2
        exit 35 ;;
    esac
    if timed_out "$started"; then
      echo "==> the stack update did not settle within ${SETTLE_TIMEOUT_SECS}s (last: ${stack_status})" >&2
      exit 35
    fi
    sleep 10
  done
elif echo "$UPDATE_OUT" | grep -q "No updates are to be performed"; then
  echo "    -> the stack already has ${TAG}; nothing to update"
else
  echo "$UPDATE_OUT" >&2
  exit 35
fi

echo "==> checking that only ${CFN_PARAM_KEY} changed"
stack_parameters > "${SCRATCH_DIR}/params-after.json"
CHANGED="$(jq -rn --slurpfile before "${SCRATCH_DIR}/params-before.json" --slurpfile after "${SCRATCH_DIR}/params-after.json" '
  ($before[0] | map({(.k): .v}) | add // {}) as $b
  | ($after[0] | map({(.k): .v}) | add // {}) as $a
  | [($b + $a) | keys[] | select($b[.] != $a[.])] | join(" ")')"
NOW="$(jq -r --arg k "$CFN_PARAM_KEY" '.[] | select(.k == $k) | .v' "${SCRATCH_DIR}/params-after.json")"
if [ "$NOW" != "$TAG" ] || { [ -n "$CHANGED" ] && [ "$CHANGED" != "$CFN_PARAM_KEY" ]; }; then
  echo "expected only ${CFN_PARAM_KEY} to change to ${TAG}; it is ${NOW} and changed: ${CHANGED:-nothing}" >&2
  exit 36
fi
echo "    -> ${CFN_PARAM_KEY} is ${TAG}; no other parameter changed"

# The newest active revision of the family is what the stack just registered. Roll it only if it
# really carries the image pushed above: a stack update that registered something else would
# otherwise roll an old image and still look like a deploy.
TD="$(aws ecs describe-task-definition --task-definition "$FAMILY" --region "$REGION" \
  --query 'taskDefinition.[family,revision]' --output text | tr '\t' ':')"
RUNNING_IMAGE="$(aws ecs describe-task-definition --task-definition "$TD" --region "$REGION" \
  --query "taskDefinition.containerDefinitions[?name=='${SERVICE_NAME}'].image | [0]" --output text)"
if [ "$RUNNING_IMAGE" != "$IMAGE_URI" ]; then
  echo "task definition ${TD} has ${RUNNING_IMAGE}, not ${IMAGE_URI}; refusing to roll" >&2
  exit 37
fi
echo "==> task definition ${TD} carries ${SERVICE_NAME}=${TAG}"

# Only this container is replaced, so only its log is captured first (SKIP_LOG_CAPTURE=1 skips it).
LOG_CAPTURE_SERVICES="$SERVICE_NAME" bash ./deploy-box.sh "$TD"
export TASKDEF="$TD"

# The deploy itself is done. End with the smoke, which reports separately, unless the caller runs it.
echo "==> deploy succeeded"
[ -z "${SMOKE_BY_COMMAND:-}" ] || { echo "==> rolled taskdef=${TASKDEF:-} tag=${TAG}"; exit 0; }
bash ./smoke-after-deploy.sh
